import urllib.request,urllib.error,json
base='https://app.ontrackegy.com'
paths=['/assets/css/app.css','/saas/console/assets/css/app.css','/assets/js/app.js','/saas/console/assets/js/app.js']
out=[]
for p in paths:
 try:
  with urllib.request.urlopen(urllib.request.Request(base+p,headers={'User-Agent':'OnTrackAssetCheck/1.0'}),timeout=5) as r:out.append({'path':p,'code':r.status,'type':r.headers.get('Content-Type')})
 except urllib.error.HTTPError as e:out.append({'path':p,'code':e.code})
 except Exception as e:out.append({'path':p,'error':type(e).__name__})
print(json.dumps(out))
